    tmp_seg2 := MID(ipText, tmp_dot2 - 1, tmp_dot1 + 1);
    tmp_seg3 := MID(ipText, tmp_dot3 - 1, tmp_dot1 + tmp_dot2 + 1);
    tmp_seg4 := MID(ipText, tmp_dot1 + tmp_dot2 + tmp_dot3, tmp_dot1 + tmp_dot2 + tmp_dot3 + 1);", "new": "    tmp_seg1 := LEFT(ipText, tmp_dot1 - 1);
    tmp_seg2 := MID(ipText, tmp_dot1 + 1, tmp_dot2 - tmp_dot1 - 1);
    tmp_seg3 := MID(ipText, tmp_dot2 + 1, tmp_dot3 - tmp_dot2 - 1);
    tmp_seg4 := MID(ipText, tmp_dot3 + 1, LEN(ipText) - tmp_dot3);"},
